cd /tmp/probe-cfgtypes && python3 - <<'EOF'
import json,subprocess,re
D='/tmp/probe-cfgtypes'; EXE='/workspace/executable'
ev=json.load(open(D+'/enumvals.json'))
canon={
 'TIMESTAMP':['YES','NO','DATETIME','DATE'],
 'WARN_AS_ERROR':['NO','YES','FAIL_ON_WARNINGS','FAIL_ON_WARNINGS_PRINT'],
 'HTML_COLORSTYLE':['LIGHT','DARK','AUTO_LIGHT','AUTO_DARK','TOGGLE'],
 'HTML_FORMULA_FORMAT':['png','svg'],
 'LATEX_BATCHMODE':['NO','YES','BATCH','NON_STOP','SCROLL','ERROR_STOP'],
 'CLASS_GRAPH':['NO','YES','TEXT','GRAPH','BUILTIN'],
 'MATHJAX_FORMAT':['HTML-CSS','NativeMML','chtml','SVG'],
}
for n,v in ev.items():
    if n in canon: continue
    seen={}
    for x in v: seen.setdefault(x.lower(),x)
    canon[n]=list(seen.values())
def ok(n,val):
    open(D+'/e.cfg','w').write('%s = %s\n'%(n,val))
    r=subprocess.run([EXE,'-x',D+'/e.cfg'],capture_output=True,text=True,cwd=D)
    return ('for option %s is not a valid'%n) not in r.stderr
bad=[]; tested=0
def mixed(sx): return ''.join(c.upper() if i%2 else c.lower() for i,c in enumerate(sx))
for n,vals in canon.items():
    for v in vals:
        for var in {v, v.lower(), v.upper(), mixed(v)}:
            tested+=1
            if not ok(n,var): bad.append((n,v,var))
print('case-variant probes:',tested,'failures:',len(bad))
for b in bad[:20]: print('  FAIL',b)
# also confirm counts match doc-derived sets
for n in sorted(canon): print(n,'->',len(canon[n]),'|',','.join(canon[n]))
json.dump(canon,open(D+'/enumcanon.json','w'),indent=1)
EOF
